// Security rules for apps generated by AI builders (Lovable, Bolt, Replit, Cursor).
// Each rule inspects one file and returns findings. Rules are deterministic on purpose:
// the same repo always gives the same report, and every finding points to a file and line.

const SEVERITY = { CRITICAL: 'Critical', HIGH: 'High', MEDIUM: 'Medium' };

function lineOf(text, index) {
  return text.slice(0, index).split('\n').length;
}

function isClientPath(path) {
  return /(^|\/)(src\/(components|pages|app|hooks|lib)|app\/|pages\/|components\/|public\/)/.test(path) &&
    !/(^|\/)(supabase\/functions|api\/|server\/|functions\/|netlify\/|\.github\/)/.test(path);
}

function isSqlMigration(path) {
  return /\.sql$/i.test(path);
}

function isCode(path) {
  return /\.(js|jsx|ts|tsx|mjs|cjs|vue|svelte)$/i.test(path);
}

const SECRET_PATTERNS = [
  { name: 'Stripe live secret key', re: /\bsk_live_[0-9a-zA-Z]{16,}\b/g },
  { name: 'Stripe restricted key', re: /\brk_live_[0-9a-zA-Z]{16,}\b/g },
  { name: 'OpenAI API key', re: /\bsk-(?:proj-)?[A-Za-z0-9_-]{32,}\b/g },
  { name: 'Anthropic API key', re: /\bsk-ant-[A-Za-z0-9_-]{32,}\b/g },
  { name: 'AWS access key ID', re: /\bAKIA[0-9A-Z]{16}\b/g },
  { name: 'GitHub token', re: /\bgh[pousr]_[A-Za-z0-9]{36,}\b/g },
  { name: 'Resend API key', re: /\bre_[A-Za-z0-9]{8,}_[A-Za-z0-9]{16,}\b/g },
];

function decodeJwtRole(token) {
  try {
    const payload = token.split('.')[1];
    const json = Buffer.from(payload.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
    return JSON.parse(json).role || null;
  } catch (e) {
    return null;
  }
}

const rules = [
  {
    id: 'VCG001',
    title: 'Hard-coded secret key in the repository',
    severity: SEVERITY.CRITICAL,
    check(path, text) {
      if (/\.(md|lock)$/i.test(path) || /\.example$|\.sample$/i.test(path)) return [];
      const out = [];
      for (const p of SECRET_PATTERNS) {
        p.re.lastIndex = 0;
        let m;
        while ((m = p.re.exec(text))) {
          out.push({ line: lineOf(text, m.index), detail: `${p.name} found in source.` });
        }
      }
      return out;
    },
    fix: 'Revoke the key in the provider dashboard now (it is already public in git history), move it to a server-side environment variable, and read it only in backend code.',
  },
  {
    id: 'VCG002',
    title: 'Supabase service_role key used or shipped in client code',
    severity: SEVERITY.CRITICAL,
    check(path, text) {
      const out = [];
      const jwtRe = /eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g;
      let m;
      while ((m = jwtRe.exec(text))) {
        if (decodeJwtRole(m[0]) === 'service_role') {
          out.push({ line: lineOf(text, m.index), detail: 'A JWT with role "service_role" is committed. It bypasses every RLS policy.' });
        }
      }
      if (isCode(path) && isClientPath(path)) {
        const envRe = /(VITE_|NEXT_PUBLIC_|REACT_APP_|EXPO_PUBLIC_)?SUPABASE_SERVICE_ROLE(_KEY)?/g;
        while ((m = envRe.exec(text))) {
          out.push({ line: lineOf(text, m.index), detail: 'Service role key referenced from browser code.' });
        }
      }
      return out;
    },
    fix: 'Rotate the service_role key in Supabase → Settings → API. Use only the anon key in the browser; keep service_role inside Edge Functions or your server.',
  },
  {
    id: 'VCG003',
    title: 'Table created without Row Level Security',
    severity: SEVERITY.HIGH,
    check(path, text) {
      if (!isSqlMigration(path)) return [];
      const out = [];
      const createRe = /create\s+table\s+(?:if\s+not\s+exists\s+)?((?:"?[\w]+"?\.)?"?([\w]+)"?)/gi;
      let m;
      while ((m = createRe.exec(text))) {
        const table = m[2];
        const rlsRe = new RegExp(`alter\\s+table\\s+(?:only\\s+)?(?:"?\\w+"?\\.)?"?${table}"?\\s+enable\\s+row\\s+level\\s+security`, 'i');
        if (!rlsRe.test(text)) {
          out.push({ line: lineOf(text, m.index), detail: `Table "${table}" has no "enable row level security" in this migration. With the public anon key anyone can read and write it.` });
        }
      }
      return out;
    },
    fix: 'Add `alter table <name> enable row level security;` and owner-scoped policies, e.g. `using (auth.uid() = user_id)` for select/update/delete and `with check (auth.uid() = user_id)` for insert.',
  },
  {
    id: 'VCG004',
    title: 'RLS policy that allows everyone',
    severity: SEVERITY.HIGH,
    check(path, text) {
      if (!isSqlMigration(path)) return [];
      const out = [];
      const polRe = /create\s+policy[\s\S]*?;/gi;
      let m;
      while ((m = polRe.exec(text))) {
        const stmt = m[0];
        const permissive = /(using|with\s+check)\s*\(\s*true\s*\)/i.test(stmt);
        const readOnlyPublic = /for\s+select/i.test(stmt) && /to\s+anon/i.test(stmt) === false && /using\s*\(\s*true\s*\)/i.test(stmt);
        if (permissive && !readOnlyPublic) {
          out.push({ line: lineOf(text, m.index), detail: 'Policy uses `(true)` for a write or all operations, so RLS is enabled but protects nothing.' });
        }
      }
      return out;
    },
    fix: 'Replace `(true)` with an ownership check such as `auth.uid() = user_id`. Keep `using (true)` only for deliberately public, read-only data.',
  },
  {
    id: 'VCG005',
    title: 'Stripe webhook handler without signature verification',
    severity: SEVERITY.HIGH,
    check(path, text) {
      if (!isCode(path)) return [];
      const looksLikeWebhook = /webhook/i.test(path) || /checkout\.session\.completed|customer\.subscription\.|invoice\.paid|payment_intent\.succeeded/.test(text);
      if (!looksLikeWebhook || !/stripe/i.test(text)) return [];
      if (/constructEvent(Async)?\s*\(/.test(text)) return [];
      const idx = text.search(/checkout\.session\.completed|customer\.subscription\.|invoice\.paid|payment_intent\.succeeded|webhook/i);
      return [{ line: lineOf(text, Math.max(idx, 0)), detail: 'Handles Stripe events but never calls stripe.webhooks.constructEvent(), so anyone can POST a fake "payment succeeded" event.' }];
    },
    fix: 'Read the raw request body and call `stripe.webhooks.constructEvent(rawBody, signatureHeader, STRIPE_WEBHOOK_SECRET)` before trusting the event; return 400 if it throws.',
  },
  {
    id: 'VCG006',
    title: 'Environment file committed to git',
    severity: SEVERITY.HIGH,
    check(path, text) {
      if (!/(^|\/)\.env(\.(local|production|prod|development))?$/i.test(path)) return [];
      const keys = (text.match(/^[A-Z0-9_]+=.+$/gm) || []).length;
      if (!keys) return [];
      return [{ line: 1, detail: `${keys} variable(s) committed in ${path}.` }];
    },
    fix: 'Delete the file from the repo, add `.env*` to .gitignore, and rotate every secret it contained; git history keeps old values.',
  },
  {
    id: 'VCG007',
    title: 'Admin check done only in the browser',
    severity: SEVERITY.MEDIUM,
    check(path, text) {
      if (!isCode(path) || !isClientPath(path)) return [];
      const out = [];
      const re = /(isAdmin|role\s*===?\s*['"]admin['"]|user\.email\s*===?\s*['"][^'"]+@[^'"]+['"])/g;
      let m;
      while ((m = re.exec(text))) {
        out.push({ line: lineOf(text, m.index), detail: 'Access decision made in client code; it can be bypassed by calling the API directly.' });
        if (out.length >= 3) break;
      }
      return out;
    },
    fix: 'Enforce the same rule on the server: an RLS policy that checks a roles table, or a backend check before the privileged operation.',
  },
];

module.exports = { rules, SEVERITY, decodeJwtRole };
